    "explanation": "Let x be the amount invested at 6% and y be the amount at 11%.\nSystem of equations:\n1) x + y = 10400\n2) 0.06x + 0.11y = 1079\nMultiply the second equation by 100: 6x + 11y = 107900.\nFrom (1), y = 10400 - x.\nSubstitute into the modified second equation:\n6x + 11(10400 - x) = 107900\n6x + 114400 - 11x = 107900\n-5x = -6500\n-5x = -6500\nx = 1300.\nSo, x = $1300.",
